inputs = ['gvab', 'jaf', 'agz', 'ygw', 'wxfdg']
outputs = ['huab', 'gfaf', 'akkgz', 'ukkgw', 'wkcfdkkg']

print("Detailed analysis:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")
    # Let's see character by character
    in_str, out_str = inputs[i], outputs[i]
    print(f"  Lengths: {len(in_str)} -> {len(out_str)}")

    # Find differences
    diff_positions = []
    for j in range(min(len(in_str), len(out_str))):
        if in_str[j] != out_str[j]:
            diff_positions.append((j, in_str[j], out_str[j]))

    if len(in_str) != len(out_str):
        if len(in_str) > len(out_str):
            # Removed characters
            for j in range(len(out_str)):
                if in_str[j] != out_str[j]:
                    diff_positions.append((j, in_str[j], out_str[j]))
            # Handle extra characters at the end
            if len(in_str) > len(out_str):
                for j in range(len(out_str), len(in_str)):
                    diff_positions.append((j, in_str[j], 'DELETED'))
        else:
            # Added characters
            for j in range(len(in_str)):
                if in_str[j] != out_str[j]:
                    diff_positions.append((j, in_str[j], out_str[j]))
            # Handle extra characters at the end
            if len(out_str) > len(in_str):
                for j in range(len(in_str), len(out_str)):
                    diff_positions.append((j, 'ADDED', out_str[j]))

    print(f"  Differences: {diff_positions}")
    print()

